# Code generated by Claude
"""
Tests of addendum J (David 2026-10-23): the carry check (J1 revised, M180: the pie slice, src/stance_select.carry_blocked / carry_blocked_mask / slice_distance) and the held beaker in the home clearance and the creep-in sweep (J2, src/home_clearance_map.held_clear_mask).
Needs the model and EGL; no pipeline run.

    MUJOCO_GL=egl python experiments/transit_clearance_test.py

1. the carry slice, geometry only: an obstacle inside the slice shorter than the old line's height but taller than the beaker's bottom is blocked (the old line check passed it); one in the arc's bulge,
   off the straight line between the grasp points, is blocked; one inside the slice shorter than the beaker's bottom passes; one outside the slice passes; the margin is the slice's own (120 mm);
   the steps' own targets are not obstacles; the grid mask agrees with the single-spot check.
2. two objects with an obstacle between them: k=2 is rejected (no candidate spot survives the filter), k=1 passes, each step gets its own navigation; the run reached holding the beaker counts it.
3. two objects with nothing between them: k=2 passes as before; switching the check off changes nothing there, and with the obstacle it lets k=2 through.
   An obstacle that blocks the best spot's carry but not a lower-scoring spot's: that spot is chosen and k stays 2 (filter, then rank).
4. J2: the held beaker in the home clearance and the creep-in sweep: a pedestal height where the arms alone are clear and the held beaker is not is caught; a height with clearance passes; the held mask is
   never more permissive than the arms'; along the creep-in path the beaker alone is checked.
"""

import copy
import math
import os
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
sys.path.insert(0, str(PROJECT_ROOT / "experiments"))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import numpy as np  # noqa: E402

from src import bench_stance as bs  # noqa: E402
from src.mpvi_postprocess import postprocess  # noqa: E402
from src.stance_select import carry_blocked, carry_blocked_mask, carry_bottom_z, make_context, run_transit_blocked, select_bench_stance, shoulder_xy, slice_distance  # noqa: E402
from src.task_beaker_hotplate import load_task  # noqa: E402
from src.task_config import BEAKER_CFG, BENCH_STANCE_CFG, PICK_PLACE_CFG, STANCE_REQUIREMENTS, TASK_CFG  # noqa: E402
from stance_select_test import PLAN4, pillar, world  # noqa: E402

results = []


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}", flush=True)


def cyl(name, xy, r, z0=0.96, z1=1.2):
    return {"name": name, "xy": xy, "radius": r, "z0": z0, "z1": z1}


def main():
    quiet = lambda *_: None
    cfg = copy.deepcopy(BENCH_STANCE_CFG)
    print("1. the carry slice (geometry)")
    top = 0.96
    a = {"xy": (1.0, 0.66), "surface_z": top, "height": 0.10, "entry": "beaker", "extra_obstacles": [], "step": 1}
    b = {"xy": (0.8, 0.66), "surface_z": top + 0.068, "height": 0.10, "entry": "hotplate", "extra_obstacles": [], "step": 3}
    sh = np.array([0.88, 1.10])                                  # a shoulder about 45 cm behind the grasp points, as at a real stance
    zb = carry_bottom_z(a, b, cfg)
    z_line = top + 0.068 + 0.10                                  # the old line's height: the carried object's top on the higher surface
    rr_old = 0.03 + 0.06                                         # the old margin: obstacle_margin_m + arm_radius_m

    def old_line_blocked(c):
        """The removed line check, kept here to show what it passed."""
        p0, p1 = np.asarray(a["xy"], float), np.asarray(b["xy"], float)
        seg = p1 - p0
        t = min(max(float((np.asarray(c["xy"], float) - p0) @ seg) / float(seg @ seg), 0.0), 1.0)
        gap = max(float(np.linalg.norm(np.asarray(c["xy"], float) - (p0 + t * seg))) - c["radius"], 0.0)
        return math.hypot(gap, max(c["z0"] - z_line, z_line - c["z1"], 0.0)) < rr_old

    print(f"    carried beaker's bottom {zb:.3f} m, old line height {z_line:.3f} m, slice margin {1000 * cfg['carry_slice_margin_m']:.0f} mm")
    check("the slice margin is its own setting, 120 mm, not obstacle_margin_m + arm_radius_m", abs(cfg["carry_slice_margin_m"] - 0.12) < 1e-12 and cfg["carry_slice_margin_m"] != cfg["obstacle_margin_m"] + cfg["arm_radius_m"])
    c1 = cyl("post", (0.895, 0.86), 0.03, 0.96, 1.10)           # 20 cm in front of the line toward the shoulder: inside the slice; top 1.10 m: under the old line height (1.128), above the beaker's bottom (1.068)
    check("an obstacle inside the slice, shorter than the old line but taller than the beaker's bottom, is blocked", carry_blocked(a, b, [c1], sh, cfg) is not None and c1["z1"] < z_line and c1["z1"] > zb, f"{carry_blocked(a, b, [c1], sh, cfg)}")
    check("... and the old line check passed it", not old_line_blocked(c1))
    mid = (np.asarray(a["xy"]) + np.asarray(b["xy"])) / 2
    out_dir = (mid - sh) / np.linalg.norm(mid - sh)
    cfg0 = {**cfg, "carry_slice_margin_m": 0.001}     # 1 mm: the check blocks when the gap is under the margin, so an exact 0 never blocks
    c2 = cyl("bulge", tuple(mid + 0.010 * out_dir), 0.005, 0.96, 1.2)    # 10 mm beyond the chord, inside the arc (the arc is about 16 mm beyond the chord at its middle), the line check's distance to the chord is over its radius
    check("an obstacle in the arc's bulge, outside the straight line between the grasp points, is blocked", carry_blocked(a, b, [c2], sh, cfg0) is not None and float(slice_distance(c2["xy"], sh, a["xy"], b["xy"])) == 0.0, f"{carry_blocked(a, b, [c2], sh, cfg0)}")
    line_gap = abs(float(np.dot(np.asarray(c2["xy"]) - np.asarray(a["xy"]), [0.0, 1.0])))
    check("... (its distance to the straight line is more than its radius)", line_gap - c2["radius"] > 0.0, f"{1000 * line_gap:.0f} mm from the line")
    c3 = cyl("coin", (0.895, 0.86), 0.03, 0.96, 1.05)           # inside the slice, top under the beaker's bottom
    check("an obstacle inside the slice, shorter than the beaker's bottom, passes", carry_blocked(a, b, [c3], sh, cfg) is None and c3["z1"] < zb)
    c4 = cyl("far", (1.55, 0.86), 0.03, 0.96, 1.3)
    check("an obstacle outside the slice (more than the margin) passes", carry_blocked(a, b, [c4], sh, cfg) is None and float(slice_distance(c4["xy"], sh, a["xy"], b["xy"])) - 0.03 > cfg["carry_slice_margin_m"])
    ref = slice_distance((0.9, 0.9), sh, a["xy"], b["xy"])
    edge_pt = sh + 0.30 * (np.array([1.0, 0.66]) - sh) / np.linalg.norm(np.array([1.0, 0.66]) - sh)      # on the straight edge toward the pick's hand
    far_left = np.array([0.55, 0.80])
    d_left = float(slice_distance(far_left, sh, a["xy"], b["xy"]))
    check("the distance is 0 inside, on an edge and beyond the arc grows from the arc", float(ref) == 0.0 and float(slice_distance(edge_pt, sh, a["xy"], b["xy"])) < 1e-9 and abs(float(slice_distance(sh + 1.5 * (np.array([0.9, 0.66]) - sh) / np.linalg.norm(np.array([0.9, 0.66]) - sh), sh, a["xy"], b["xy"])) - (1.5 - max(np.hypot(*(np.array(a["xy"]) - sh)), np.hypot(*(np.array(b["xy"]) - sh))))) < 0.02)
    check("an obstacle off the slice's side is blocked exactly when its gap to the slice is under the margin", (carry_blocked(a, b, [cyl("side", tuple(far_left), 0.03)], sh, cfg) is not None) == (d_left - 0.03 < cfg["carry_slice_margin_m"]), f"{1000 * d_left:.0f} mm from the slice")
    side_pass = cyl("side2", (0.25, 0.80), 0.03)
    check("... and an obstacle farther off the side passes", carry_blocked(a, b, [side_pass], sh, cfg) is None)
    check("the steps' own targets are not obstacles (the hotplate is the pick's obstacle)", carry_blocked({**a, "extra_obstacles": [cyl("hotplate", (0.8, 0.66), 0.09, 0.96, 1.03)]}, b, [], sh, cfg) is None)
    X, Y = np.meshgrid(np.array([0.6, 0.7, 0.8]), np.array([1.0, 1.1, 1.2]))
    objs = [{**a, "z_points": [], "name": "1:beaker", "radius": 0.035, "z0": 0.96, "z1": 1.06}, {**b, "name": "3:hotplate", "radius": 0.09, "z0": 0.96, "z1": 1.028}]
    objs[0]["extra_obstacles"] = [c1]
    mask = carry_blocked_mask(objs, X, Y, ctx_yaw := -math.pi / 2, {"shoulder": {"left": (0.0, 0.09, 1.0)}}, "left", cfg)
    one = np.array([[run_transit_blocked(objs, cfg, shoulder_xy({"shoulder": {"left": (0.0, 0.09, 1.0)}}, "left", (X[i, j], Y[i, j]), ctx_yaw)) is not None for j in range(3)] for i in range(3)])
    check("the grid mask agrees with the single-spot check at every spot", bool((mask == one).all()), f"{mask.astype(int).tolist()} vs {one.astype(int).tolist()}")

    sim = load_task()
    m, d = sim.model, sim.data
    maps = bs.load_maps("data/reach_map", sides=("left",))
    ctx = make_context(m, d, maps)
    tagged = postprocess(PLAN4, False, say=quiet)

    print("\n2. an obstacle between the objects")
    hp_xy = (0.70, 0.66)                                       # 30 cm from the beaker (1.0, 0.66): the post at 0.85 is 15 cm from each, outside the filter's reach around either grasp point
    w = world(hotplate_xy=hp_xy, extra=[pillar((0.85, 0.66), 0.25, radius=0.03)])
    sel = select_bench_stance(tagged, w, TASK_CFG, ctx, cfg, say=quiet)
    rep = sel["report"]
    cf = [t for t in rep.get("carry_filter", []) if t["steps"] == [1, 3]]
    print(f"    ok {sel['ok']}; stop {sel['stop']}; runs {[(r['steps'], r['nav'], np.round(r['stance']['xy'], 3).tolist(), r['stance']['q']) for r in rep['runs']]}; null nav {rep['null_nav']}; carry filter {rep.get('carry_filter')}; notes {rep['notes']}")
    check("k=2 is rejected: the carry filter removed spots and none of the rest covers both steps", bool(cf) and cf[0]["spots_removed"] > 0 and not any(r["steps"] == [1, 3] for r in rep["runs"]), f"{cf[:1]}")
    named = run_transit_blocked([t for t in [{**a, "name": "1:beaker", "radius": 0.035, "z0": 0.96, "z1": 1.06, "extra_obstacles": [{"name": "pillar", "xy": (0.85, 0.66), "radius": 0.03, "z0": 0.96, "z1": 1.21}]}, {**b, "name": "3:hotplate", "radius": 0.09, "z0": 0.96, "z1": 1.028}]], cfg, sh)
    check("the single-spot check names the obstacle", named is not None and named["obstacle"] == "pillar", f"{named}")
    check("k=1 passes: two runs, one step each", sel["ok"] and [r["steps"] for r in rep["runs"]] == [[1], [3]], f"{[r['steps'] for r in rep['runs']]}")
    check("each step gets its own navigation (none is null)", [r["nav"] for r in rep["runs"]] == [[0], [2]] and rep["null_nav"] == [], f"{[r['nav'] for r in rep['runs']]} {rep['null_nav']}")
    check("the pick returns to the zombie pose before the second navigation (end_at_zombie)", sel["ok"] and sel["plan"]["segments"][1].get("end_at_zombie") is True)
    check("the second run is reached holding the beaker and says so", any("holding the beaker" in n for n in rep["notes"]), f"{rep['notes']}")
    sw = select_bench_stance(tagged, w, TASK_CFG, ctx, {**cfg, "transit_check": False}, say=quiet)
    check("with the check off the same world lets k=2 through (the switch is the only difference)", sw["ok"] and [r["steps"] for r in sw["report"]["runs"]] == [[1, 3]], f"{[r['steps'] for r in sw['report']['runs']] if sw['ok'] else sw['stop']}")

    print("\n3. nothing between the objects; and the best spot blocked")
    sel0 = select_bench_stance(tagged, world(hotplate_xy=hp_xy), TASK_CFG, ctx, cfg, say=quiet)
    r0 = sel0["report"]
    check("k=2 passes as before (same 30 cm spacing, no post): one run with both steps, the second navigation step null", sel0["ok"] and [r["steps"] for r in r0["runs"]] == [[1, 3]] and r0["null_nav"] == [2] and r0["carry_filter"][0]["spots_removed"] == 0, f"{r0.get('carry_filter')}")
    S0 = sel0["report"]["runs"][0]["stance"]
    print(f"    best spot without the post: {np.round(S0['xy'], 3).tolist()} pedestal {S0['q']}; carry check time {1000 * r0.get('carry_check_seconds', 0):.1f} ms for {r0['carry_filter'][0]['spots']} spots")
    post = pillar((0.60, 0.90), 0.25, radius=0.03)             # left of the best spot's slice by less than the margin, farther from the second-ranked spot's
    selb = select_bench_stance(tagged, world(hotplate_xy=hp_xy, extra=[post]), TASK_CFG, ctx, cfg, say=quiet)
    rb = selb["report"]
    sb = rb["runs"][0]["stance"] if selb["ok"] else None
    blocked_best = run_transit_blocked([{**a, "name": "1:beaker", "radius": 0.035, "z0": 0.96, "z1": 1.06, "extra_obstacles": [{"name": "pillar", "xy": (0.60, 0.90), "radius": 0.03, "z0": 0.96, "z1": 1.21}]},
                                        {**b, "xy": hp_xy, "name": "3:hotplate", "radius": 0.09, "z0": 0.96, "z1": 1.028}], cfg, shoulder_xy(ctx.rg, cfg["arm"], S0["xy"], ctx.yaw))
    print(f"    the post's distance to the best spot's slice: {1000 * float(slice_distance((0.60, 0.90), shoulder_xy(ctx.rg, cfg['arm'], S0['xy'], ctx.yaw), a['xy'], hp_xy)):.0f} mm")
    print(f"    with the post at (0.60, 0.90): {None if sb is None else (np.round(sb['xy'], 3).tolist(), sb['q'])}, runs {[r['steps'] for r in rb['runs']]}, carry filter {rb.get('carry_filter')}")
    check("the best spot is blocked for the carry by the post", blocked_best is not None, f"{blocked_best}")
    check("a lower-scoring unblocked spot is chosen instead, with k unchanged (one run of both steps)", selb["ok"] and [r["steps"] for r in rb["runs"]] == [[1, 3]] and tuple(np.round(sb["xy"], 3)) != tuple(np.round(S0["xy"], 3)), f"{None if sb is None else np.round(sb['xy'], 3).tolist()}")
    check("the chosen spot's own carry is clear and it is one of the ranked spots of the baseline", selb["ok"] and run_transit_blocked([{**a, "name": "1:beaker", "radius": 0.035, "z0": 0.96, "z1": 1.06, "extra_obstacles": [{"name": "pillar", "xy": (0.60, 0.90), "radius": 0.03, "z0": 0.96, "z1": 1.21}]},
                                        {**b, "xy": hp_xy, "name": "3:hotplate", "radius": 0.09, "z0": 0.96, "z1": 1.028}], cfg, shoulder_xy(ctx.rg, cfg["arm"], sb["xy"], ctx.yaw)) is None and any(tuple(np.round(r["xy"], 3)) == tuple(np.round(sb["xy"], 3)) for r in r0["runs"][0]["ranked"]))

    print("\n4. the held beaker in the home clearance and the creep-in sweep")
    hcm = ctx.hcm
    rad, hgt, frac = BEAKER_CFG["outer_diameter"] / 2, BEAKER_CFG["height"], PICK_PLACE_CFG["grasp_height_frac"]
    qs = list(np.round(np.arange(0.05, 0.2501, 0.01), 3))
    yaw = ctx.yaw
    x0, y0 = TASK_CFG["staging_xy"]
    X, Y = np.array([[x0]]), np.array([[y0]])
    arms = hcm.clear_mask(yaw, qs, X, Y)[:, 0, 0]
    bk = hcm.clear_mask(yaw, qs, X, Y, points=hcm.held_points(rad, hgt, frac))[:, 0, 0]
    held = hcm.held_clear_mask(yaw, qs, X, Y, rad, hgt, frac)[:, 0, 0]
    held_creep = hcm.held_clear_mask(yaw, qs, X, Y, rad, hgt, frac, TASK_CFG["staging_approach_back_m"])[:, 0, 0]
    print("    q     arms  beaker  held(stance)  held(+creep path)")
    for i, q in enumerate(qs):
        print(f"    {q:.2f}  {int(arms[i])}     {int(bk[i])}       {int(held[i])}             {int(held_creep[i])}")
    check("the held mask is never more permissive than the arms' alone", not np.any(held & ~arms) and not np.any(held_creep & ~held))
    caught = [q for i, q in enumerate(qs) if arms[i] and not bk[i]]
    ok_both = [q for i, q in enumerate(qs) if arms[i] and held_creep[i]]
    check("a pedestal height where the arms alone are clear but the held beaker is not is caught", bool(caught) and not any(held[qs.index(q)] for q in caught), f"heights {caught}")
    check("a pedestal height with clearance for the arms and the beaker passes, at the stance and along the creep-in path", bool(ok_both), f"heights {ok_both[:6]}")
    check("the 40 mm threshold is the home clearance's", abs(hcm.min_clear - STANCE_REQUIREMENTS["home_min_clearance"]) < 1e-12 and abs(hcm.min_clear - 0.04) < 1e-12)
    print(f"\n{sum(results)}/{len(results)} checks passed")
    return all(results)


if __name__ == "__main__":
    sys.exit(0 if main() else 1)
